import torch


def run(x, fill_value):
    return torch.full_like(x, fill_value)


def valid(ref_outputs, sol_outputs, inputs, ctx):
    import torch
    ref = ref_outputs[0].detach().to("cpu")
    sol = sol_outputs[0].detach().to("cpu")
    if tuple(ref.shape) != tuple(sol.shape):
        return {"passed": False, "message": f"shape {tuple(sol.shape)} vs {tuple(ref.shape)}", "metrics": {}}
    if ref.dtype != sol.dtype:
        return {"passed": False, "message": f"dtype {sol.dtype} vs {ref.dtype}", "metrics": {}}
    r = ref.to(torch.float64)
    s = sol.to(torch.float64)
    eq = (r == s)
    both_nan = torch.isnan(r) & torch.isnan(s)
    ok = (eq | both_nan).all().item()
    return {"passed": bool(ok), "message": "", "metrics": {}}
